iterate.script:
try {
                            if (chg.mode == 'forever') darpan.admin.SettingAdminSupport.remove(ec, chg.key, "admin.RetentionAdminServices.update#RetentionPeriods")
                            else darpan.admin.SettingAdminSupport.save(ec, chg.key, chg.after.toString(), previewNote, "admin.RetentionAdminServices.update#RetentionPeriods")
                            if (ec.message.hasError()) throw new IllegalStateException(ec.message.errorsString)
                            savedTables.add(chg.table)
                        } catch (Exception e) {
                            ec.message.clearErrors()
                            ec.message.addError('Saving ' + chg.table + ' failed (' + e.message + '). Saved before it: ' + (savedTables ? savedTables.join(', ') : 'none') +
                                    '. Not saved: ' + plan.changes.collect { it.table }.findAll { !savedTables.contains(it) }.join(', ') + '. Check with get#RetentionPeriods and retry.')
                            return
                        }
